import java.util.*;

class Solution {
    public int[][] addBooking(int[][] booked, int[] extra) {
        List<int[]> out = new ArrayList<>();
        int lo = extra[0], hi = extra[1];
        int i = 0, n = booked.length;
        while (i < n && booked[i][1] < lo) out.add(booked[i++]);      // strictly before
        while (i < n && booked[i][0] <= hi) {                          // overlaps or touches
            lo = Math.min(lo, booked[i][0]);
            hi = Math.max(hi, booked[i][1]);
            i++;
        }
        out.add(new int[]{lo, hi});
        while (i < n) out.add(booked[i++]);                            // strictly after
        return out.toArray(new int[0][]);
    }
}

