class Solution:
    def addBooking(self, booked: List[List[int]], extra: List[int]) -> List[List[int]]:
        s, e = extra
        out, i, n = [], 0, len(booked)
        while i < n and booked[i][1] < s:
            out.append(booked[i]); i += 1
        while i < n and booked[i][0] <= e:
            s = min(s, booked[i][0]); e = max(e, booked[i][1]); i += 1
        out.append([s, e])
        out.extend(booked[i:])
        return out

